def load_raw(archives):
    import zstandard
    location=Path(os.environ.get('FM24_DB_DIR',ROOT/'scratch/data')).resolve()
    if location.drive.upper()=='Z:': raise ValueError('Z: is forbidden')
    def decompress(blob):
        check(blob[:4]==bytes.fromhex('28b52ffd'),'frame signature')
